class Solution {
public:
    int numberOfGoodPaths(std::vector<int>& vals, std::vector<std::vector<int>>& edges) {
        int n = vals.size();
        std::vector<int> parent(n), max_val = vals, count(n, 1);
        std::iota(parent.begin(), parent.end(), 0);

        std::function<int(int)> find = [&](int i) {
            return parent[i] == i ? i : (parent[i] = find(parent[i]));
        };

        std::sort(edges.begin(), edges.end(), [&](const auto& a, const auto& b) {
            return std::max(vals[a[0]], vals[a[1]]) < std::max(vals[b[0]], vals[b[1]]);
        });

        int ans = n;
        for (const auto& e : edges) {
            int ru = find(e[0]), rv = find(e[1]);
            if (ru != rv) {
                if (max_val[ru] == max_val[rv]) {
                    ans += count[ru] * count[rv];
                    parent[rv] = ru;
                    count[ru] += count[rv];
                } else if (max_val[ru] > max_val[rv]) {
                    parent[rv] = ru;
                } else {
                    parent[ru] = rv;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;
        int[] parent = new int[n];
        int[] maxVal = new int[n];
        int[] count = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            maxVal[i] = vals[i];
            count[i] = 1;
        }

        java.util.Arrays.sort(edges, (a, b) -> {
            int maxA = Math.max(vals[a[0]], vals[a[1]]);
            int maxB = Math.max(vals[b[0]], vals[b[1]]);
            return Integer.compare(maxA, maxB);
        });

        int ans = n;
        for (int[] e : edges) {
            int ru = find(parent, e[0]), rv = find(parent, e[1]);
            if (ru != rv) {
                if (maxVal[ru] == maxVal[rv]) {
                    ans += count[ru] * count[rv];
                    parent[rv] = ru;
                    count[ru] += count[rv];
                } else if (maxVal[ru] > maxVal[rv]) {
                    parent[rv] = ru;
                } else {
                    parent[ru] = rv;
                }
            }
        }
        return ans;
    }

    private int find(int[] parent, int i) {
        if (parent[i] != i) parent[i] = find(parent, parent[i]);
        return parent[i];
    }
}

var numberOfGoodPaths = function(vals, edges) {
    const n = vals.length;
    const parent = Array.from({ length: n }, (_, i) => i);
    const maxVal = [...vals];
    const count = new Array(n).fill(1);

    function find(i) {
        if (parent[i] !== i) parent[i] = find(parent[i]);
        return parent[i];
    }

    edges.sort((a, b) => {
        const maxA = Math.max(vals[a[0]], vals[a[1]]);
        const maxB = Math.max(vals[b[0]], vals[b[1]]);
        return maxA - maxB;
    });

    let ans = n;
    for (const [u, v] of edges) {
        const ru = find(u), rv = find(v);
        if (ru !== rv) {
            if (maxVal[ru] === maxVal[rv]) {
                ans += count[ru] * count[rv];
                parent[rv] = ru;
                count[ru] += count[rv];
            } else if (maxVal[ru] > maxVal[rv]) {
                parent[rv] = ru;
            } else {
                parent[ru] = rv;
            }
        }
    }
    return ans;
};
